-- AlterTable: description — флейвор-текст предмета (задача "перезалить
-- каталог предметов"). Раньше UI показывал флейвор из отдельного
-- захардкоженного мок-массива в App.tsx (вкладка "Магазин"/книги), не из
-- БД — колонки не было вообще. Nullable, тем же стилем, что остальные
-- "не у каждого слота" поля (damage/armor/moveSpeed/luck) — реальный
-- consumer в UI пока не подключён, это отдельный шаг.
ALTER TABLE "Item" ADD COLUMN "description" TEXT;

-- DataMigration: полная перезаливка каталога предметов (задача "перезалить
-- каталог предметов"). Старый каталог (см. server/prisma/seed-items.ts до
-- этой миграции) — 10 тиров оружие/броня + 5 тиров шлем/сапоги/перчатки/
-- амулет, сеттинг гномы/викинги/некроманты, moveSpeed множителем
-- (1.05..1.25). Новый — 6 тиров на ВСЕ 6 слотов, levelRequired = tier*5,
-- moveSpeed ПРОЦЕНТОМ (2..10, не множитель — единственный код, читающий
-- это поле, server/src/routes/run.ts, просто ретранслирует его клиенту
-- как есть, никакой математики с ним нигде не делается), лестница
-- названий и флейвор-тексты — см. CLAUDE.md "СПИСОК ПРЕДМЕТОВ"
-- (ржавый/драный → солдатский → дознавателя → гвардейский → безымянного →
-- правого места).
--
-- InventoryItem удаляется ПЕРВЫМ: FK InventoryItem.itemId -> Item.id стоит
-- ON DELETE RESTRICT (см. 20260630143413_add_equipment_models/migration.sql)
-- — удаление Item с живыми InventoryItem иначе упадёт с ошибкой FK. У
-- персонажа 1 в инвентаре лежит ВЕСЬ старый каталог (отладочный мусор) —
-- удаляется вместе со всеми остальными InventoryItem без разбора по
-- персонажу, другого source of truth для инвентаря нет и других
-- персонажей с предметами на момент написания миграции тоже нет.
DELETE FROM "InventoryItem";
DELETE FROM "Item";

-- id — вручную (не cuid()): cuid() генерируется Prisma Client'ом на уровне
-- приложения, а не DB DEFAULT (см. CreateTable в
-- 20260630143413_add_equipment_models/migration.sql — там нет DEFAULT для
-- "id"), так что сырой SQL INSERT обязан задать id сам. Читаемые слаги
-- "<slot>_t<tier>" вместо случайных строк — стабильны между реseed'ами,
-- не встречались нигде в коде как хардкод (грепом проверено), формату TEXT
-- ничем не противоречат.
